previewCss:
.darma-loader-darma-b17-x-ray-scan { --accent: var(--loader-color, #0ea5e9); --accent-2: var(--loader-secondary-color, #e0f2fe); width: var(--loader-size, 120px); height: calc(var(--loader-size, 120px) * .82); position: relative; overflow: hidden; border-radius: 8px; }
.darma-loader-darma-b17-x-ray-scan .darma-loader-darma-b17-x-ray-scan__plate { position: absolute; inset: 0; border-radius: 8px; background: linear-gradient(color-mix(in srgb, var(--accent) 30%, transparent), color-mix(in srgb, var(--accent) 10%, transparent)); }
.darma-loader-darma-b17-x-ray-scan .darma-loader-darma-b17-x-ray-scan__spine { position: absolute; left: 47%; top: 10%; width: 6%; height: 80%; border-radius: 4px; background: repeating-linear-gradient(color-mix(in srgb, var(--accent-2) 70%, transparent) 0 62%, transparent 0 100%); background-size: 100% 14%; }
.darma-loader-darma-b17-x-ray-scan span { position: absolute; left: 14%; right: 14%; height: 12%; border: 4px solid color-mix(in srgb, var(--accent-2) 32%, transparent); border-top: 0; border-radius: 0 0 60% 60% / 0 0 100% 100%; animation: darma-loader-darma-b17-x-ray-scan-xray-rib calc(var(--loader-speed, 1s) * 2.6) ease-in-out infinite; }
.darma-loader-darma-b17-x-ray-scan span:nth-of-type(1) { top: 16%; }
.darma-loader-darma-b17-x-ray-scan span:nth-of-type(2) { top: 32%; animation-delay: calc(var(--loader-speed, 1s) * .18); }
.darma-loader-darma-b17-x-ray-scan span:nth-of-type(3) { top: 48%; animation-delay: calc(var(--loader-speed, 1s) * .36); }
.darma-loader-darma-b17-x-ray-scan span:nth-of-type(4) { top: 64%; animation-delay: calc(var(--loader-speed, 1s) * .54); }
.darma-loader-darma-b17-x-ray-scan .darma-loader-darma-b17-x-ray-scan__beam { position: absolute; left: 0; right: 0; height: 16%; background: linear-gradient(transparent, color-mix(in srgb, var(--accent-2) 75%, transparent), transparent); animation: darma-loader-darma-b17-x-ray-scan-xray-beam calc(var(--loader-speed, 1s) * 2.6) ease-in-out infinite; }
@keyframes darma-loader-darma-b17-x-ray-scan-xray-beam { 0%, 100% { top: -12%; } 50% { top: 92%; } }
@keyframes darma-loader-darma-b17-x-ray-scan-xray-rib { 0%, 100% { border-color: color-mix(in srgb, var(--accent-2) 26%, transparent); border-top-color: transparent; } 46% { border-color: var(--accent-2); border-top-color: transparent; } }

